input.command:
export IMPLEMENT_TMPDIR=<TMPDIR>
cat "$IMPLEMENT_TMPDIR/round-1/aggregator-output.txt.events.jsonl" 2>/dev/null | python3 -c "
import sys, json
for line in sys.stdin:
    line = line.strip()
    if not line: continue
    try:
        d = json.loads(line)
        if d.get('type') == 'item.completed' and d['item'].get('type') == 'agent_message':
            print(d['item']['text'][:3000])
    except:
        pass
" 2>/dev/null | head -100
